import { generateText, stepCountIs } from "ai";
import { openai } from "@ai-sdk/openai";
import { Meilisearch } from "meilisearch";
import { describe, expect, it } from "vite-plus/test";

import { meilisearchSearch } from "../../src/tools/search.ts";
import { expectToolCallInput, expectToolCalled } from "./utils/assert-tool-calls.ts";
import { withLogging } from "./utils/logging.ts";

const { OPENAI_API_KEY, MEILISEARCH_HOST, MEILISEARCH_API_KEY, MEILISEARCH_INDEX } = process.env;

describe.skipIf(!OPENAI_API_KEY || !MEILISEARCH_HOST || !MEILISEARCH_API_KEY || !MEILISEARCH_INDEX)(
  "meilisearchSearch e2e",
  () => {
    it("uses the search tool via generateText", async () => {
      const client = new Meilisearch({
        host: MEILISEARCH_HOST!,
        apiKey: [REDACTED],
      });

      const search = meilisearchSearch({
        client,
        indexUid: MEILISEARCH_INDEX!,
        description: "Search movies by title or synopsis",
      });

      const result = await generateText({
        model: openai("gpt-4o-mini"),
        prompt: "Search for Lord of the Rings movies and summarize briefly what you find.",
        tools: { search },
        stopWhen: stepCountIs(3),
        ...withLogging(),
      });

      expectToolCalled(result, "search");
      expectToolCallInput(result, "search", { q: expect.any(String) });
      expect(result.toolResults.length).toBeGreaterThan(0);
      expect(result.text.length).toBeGreaterThan(0);
    }, 60_000);
  },
);

import { asSchema } from "ai";
import type { Meilisearch } from "meilisearch";
import { describe, expect, test, vi } from "vite-plus/test";

import { meilisearchSearch } from "../search.ts";

function createMockClient(search = vi.fn()) {
  return {
    client: {
      index: vi.fn().mockReturnValue({ search }),
    } as unknown as Meilisearch,
    search,
  };
}

const executionOptions = {
  toolCallId: "call-1",
  messages: [],
  context: {},
};

describe("meilisearchSearch", () => {
  test("exposes a validated runtime input contract for q", async () => {
    const { client } = createMockClient();

    const searchTool = meilisearchSearch({
      client,
      description: "Search the product catalog",
      indexUid: "products",
    });

    expect(searchTool.description).toBe("Search the product catalog");

    const schema = asSchema(searchTool.inputSchema);
    await expect(schema.validate?.({ q: "shoes" })).resolves.toMatchObject({
      success: true,
      value: { q: "shoes" },
    });
    await expect(schema.validate?.({ q: "" })).resolves.toMatchObject({
      success: false,
    });
    await expect(schema.validate?.({})).resolves.toMatchObject({
      success: false,
    });
  });

  test("forwards config searchParams with the runtime query", async () => {
    const searchParams = {
      hitsPerPage: 12,
      sort: ["popularity:desc"],
    };
    const { client } = createMockClient(
      vi.fn().mockImplementation(async (query: string, options) => {
        return {
          indexUid: "products",
          query,
          options,
          hits: [{ id: "p1" }],
        };
      }),
    );

    const searchTool = meilisearchSearch({
      client,
      description: "Search the product catalog",
      indexUid: "products",
      searchParams,
    });

    await expect(searchTool.execute?.({ q: "shoes" }, executionOptions as never)).resolves.toEqual({
      indexUid: "products",
      query: "shoes",
      options: searchParams,
      hits: [{ id: "p1" }],
    });
  });

  test("propagates Meilisearch errors", async () => {
    const { client } = createMockClient(vi.fn().mockRejectedValue(new Error("index not found")));

    const searchTool = meilisearchSearch({
      client,
      description: "Search the product catalog",
      indexUid: "products",
    });

    await expect(searchTool.execute?.({ q: "shoes" }, executionOptions as never)).rejects.toThrow(
      "index not found",
    );
  });
});

