describe("meilisearchSearchSimilar", () => {
  test("exposes a validated runtime input contract for id", async () => {
    const { client } = createMockClient();

    const searchSimilarTool = meilisearchSearchSimilar({
      client,
      description: "Find similar movies",
      indexUid: "movies",
    });

    expect(searchSimilarTool.description).toBe("Find similar movies");

    const schema = asSchema(searchSimilarTool.inputSchema);
    await expect(schema.validate?.({ id: "tt0120737" })).resolves.toMatchObject({
      success: true,
      value: { id: "tt0120737" },
    });
    await expect(schema.validate?.({ id: 42 })).resolves.toMatchObject({
      success: true,
      value: { id: 42 },
    });
    await expect(schema.validate?.({})).resolves.toMatchObject({
      success: false,
    });
  });

  test("forwards config searchSimilarParams with the runtime id", async () => {
    const searchSimilarParams = {
      embedder: "default",
      limit: 5,
    };
    const { client, searchSimilarDocuments } = createMockClient(
      vi.fn().mockResolvedValue({
        hits: [{ id: "tt0167260" }],
        id: "tt0120737",
      }),
    );

    const searchSimilarTool = meilisearchSearchSimilar({
      client,
      description: "Find similar movies",
      indexUid: "movies",
      searchSimilarParams,
    });

    await expect(
      searchSimilarTool.execute?.({ id: "tt0120737" }, executionOptions as never),
    ).resolves.toEqual({
      hits: [{ id: "tt0167260" }],
      id: "tt0120737",
    });

    expect(searchSimilarDocuments).toHaveBeenCalledWith({
      id: "tt0120737",
      embedder: "default",
      limit: 5,
    });
  });

  test("propagates Meilisearch errors", async () => {
    const { client } = createMockClient(vi.fn().mockRejectedValue(new Error("document not found")));

    const searchSimilarTool = meilisearchSearchSimilar({
      client,
      description: "Find similar movies",
      indexUid: "movies",
    });

    await expect(
      searchSimilarTool.execute?.({ id: "missing" }, executionOptions as never),
    ).rejects.toThrow("document not found");
  });
});

import { asSchema } from "ai";
import type { Meilisearch } from "meilisearch";
import { describe, expect, test, vi } from "vite-plus/test";

import { meilisearchMultiSearch } from "../multi-search.ts";

function createMockClient(multiSearch = vi.fn()) {
  return {
    client: {
      multiSearch,
    } as unknown as Meilisearch,
    multiSearch,
  };
}

const executionOptions = {
  toolCallId: "call-1",
  messages: [],
  context: {},
};

describe("meilisearchMultiSearch", () => {
  test("exposes a validated runtime input contract for q", async () => {
    const { client } = createMockClient();

    const multiSearchTool = meilisearchMultiSearch({
      client,
      description: "Search movies and actors",
      queries: [{ indexUid: "movies" }, { indexUid: "actors" }],
    });

    expect(multiSearchTool.description).toBe("Search movies and actors");

    const schema = asSchema(multiSearchTool.inputSchema);
    await expect(schema.validate?.({ q: "frodo" })).resolves.toMatchObject({
      success: true,
      value: { q: "frodo" },
    });
    await expect(schema.validate?.({ q: "" })).resolves.toMatchObject({
      success: false,
    });
    await expect(schema.validate?.({})).resolves.toMatchObject({
      success: false,
    });
  });

  test("builds multiSearch queries from config options and runtime query", async () => {
    const queries = [
      { indexUid: "movies", limit: 5, filter: "genre = fantasy" },
      { indexUid: "actors", limit: 3 },
    ];
    const { client, multiSearch } = createMockClient(
      vi.fn().mockResolvedValue({
        results: [{ hits: [{ id: "m1" }] }, { hits: [{ id: "a1" }] }],
      }),
    );

    const multiSearchTool = meilisearchMultiSearch({
      client,
      description: "Search movies and actors",
      federation: { limit: 10 },
      queries,
    });

    await expect(
      multiSearchTool.execute?.({ q: "frodo" }, executionOptions as never),
    ).resolves.toEqual({
      results: [{ hits: [{ id: "m1" }] }, { hits: [{ id: "a1" }] }],
    });

    expect(multiSearch).toHaveBeenCalledWith({
      federation: { limit: 10 },
      queries: [
        { indexUid: "movies", limit: 5, filter: "genre = fantasy", q: "frodo" },
        { indexUid: "actors", limit: 3, q: "frodo" },
      ],
    });
  });

  test("propagates Meilisearch errors", async () => {
    const { client } = createMockClient(
      vi.fn().mockRejectedValue(new Error("multi-search failed")),
    );

    const multiSearchTool = meilisearchMultiSearch({
      client,
      description: "Search movies and actors",
      queries: [{ indexUid: "movies" }],
    });

    await expect(
      multiSearchTool.execute?.({ q: "frodo" }, executionOptions as never),
    ).rejects.toThrow("multi-search failed");
  });
});

