import { tool } from "ai";
import type { Tool } from "ai";
import type { Meilisearch } from "meilisearch";
import { z } from "zod";

import { resolveClient } from "./resolve-client.ts";
import type { SearchToolOptions } from "./types.ts";

type SearchResult = Awaited<ReturnType<ReturnType<Meilisearch["index"]>["search"]>>;
type SearchTool = Tool<{ q: string }, SearchResult>;

/**
 * Search documents in an index
 *
 * @param options - Search tool options
 * @returns AI SDK tool that runs a Meilisearch search query
 * @see {@link https://www.meilisearch.com/docs/reference/api/search/search-with-post.md}
 */
export function meilisearchSearch(options: SearchToolOptions): SearchTool {
  const client = resolveClient(options);
  const { description, indexUid, searchParams } = options;

  return tool({
    description,
    inputSchema: z.object({
      q: z
        .string()
        .min(1)
        .max(500)
        .describe("The search query to look up in the Meilisearch index"),
    }),
    execute: async ({ q }) => {
      return client.index(indexUid).search(q, searchParams);
    },
  });
}

import { tool } from "ai";
import type { Tool } from "ai";
import type { MultiSearchResponse, SearchResponse } from "meilisearch";
import { z } from "zod";

import { resolveClient } from "./resolve-client.ts";
import type { MultiSearchToolOptions } from "./types.ts";

type MultiSearchResult = MultiSearchResponse | SearchResponse;
type MultiSearchTool = Tool<{ q: string }, MultiSearchResult>;

/**
 * Search across multiple indexes in one request
 *
 * @param options - Multi-search tool options
 * @returns AI SDK tool that runs a Meilisearch multi-search query
 * @see {@link https://www.meilisearch.com/docs/reference/api/multi-search/perform-a-multi-search.md}
 */
export function meilisearchMultiSearch(options: MultiSearchToolOptions): MultiSearchTool {
  const client = resolveClient(options);
  const { description, queries, federation } = options;

  return tool({
    description,
    inputSchema: z.object({
      q: z
        .string()
        .min(1)
        .max(500)
        .describe("The search query to look up across the configured Meilisearch indexes"),
    }),
    execute: async ({ q }): Promise<MultiSearchResult> => {
      const queriesWithQ = queries.map((query) => ({ ...query, q }));

      if (federation !== undefined) {
        return client.multiSearch({ federation, queries: queriesWithQ });
      }

      return client.multiSearch({ queries: queriesWithQ });
    },
  });
}

import { tool } from "ai";
import type { Tool } from "ai";
import type { Meilisearch } from "meilisearch";
import { z } from "zod";

import { resolveClient } from "./resolve-client.ts";
import type { SearchSimilarToolOptions } from "./types.ts";

type SearchSimilarResult = Awaited<
  ReturnType<ReturnType<Meilisearch["index"]>["searchSimilarDocuments"]>
>;
type SearchSimilarTool = Tool<{ id: string | number }, SearchSimilarResult>;

/**
 * Get documents similar to a reference document
 *
 * @param options - Search-similar tool options
 * @returns AI SDK tool that runs a Meilisearch similar-documents query
 * @see {@link https://www.meilisearch.com/docs/reference/api/similar-documents/get-similar-documents-with-post.md}
 */
export function meilisearchSearchSimilar(options: SearchSimilarToolOptions): SearchSimilarTool {
  const client = resolveClient(options);
  const { description, indexUid, searchSimilarParams } = options;

  return tool({
    description,
    inputSchema: z.object({
      id: z
        .union([z.string().min(1), z.number()])
        .describe("The document id to find similar documents for"),
    }),
    execute: async ({ id }) => {
      return client.index(indexUid).searchSimilarDocuments({
        id,
        ...searchSimilarParams,
      });
    },
  });
}

const DEFAULT_MAX_OUTPUT_CHARS = 500;

type LogGenerateTextOptions = {
  prefix?: string;
  maxOutputChars?: number;
};

type StepLog = {
  stepNumber: number;
  text: string;
  finishReason: string;
  toolCalls: Array<{ toolName: string; input: unknown }>;
  toolResults: Array<{ toolName: string; output: unknown }>;
};

type FinishLog = {
  text: string;
  steps: unknown[];
};

function truncate(value: unknown, maxChars: number): unknown {
  const serialized = JSON.stringify(value);
  if (serialized.length <= maxChars) {
    return value;
  }
  return `${serialized.slice(0, maxChars)}… (${serialized.length} chars)`;
}

/**
 * Returns `generateText` callbacks that print progress so long e2e runs aren't silent.
 */
export function withLogging(options: LogGenerateTextOptions = {}) {
  const prefix = options.prefix ?? "[e2e]";
  const maxOutputChars = options.maxOutputChars ?? DEFAULT_MAX_OUTPUT_CHARS;

  return {
    onStart() {
      console.log(`${prefix} starting generateText…`);
    },
    onStepFinish({ stepNumber, text, toolCalls, toolResults, finishReason }: StepLog) {
      console.log(`${prefix} step ${stepNumber} finished (reason: ${finishReason})`);

      if (toolCalls.length > 0) {
        console.log(
          `${prefix} tool calls:`,
          toolCalls.map((call) => ({
            toolName: call.toolName,
            input: call.input,
          })),
        );
      }

      if (toolResults.length > 0) {
        console.log(
          `${prefix} tool results:`,
          toolResults.map((toolResult) => ({
            toolName: toolResult.toolName,
            output: truncate(toolResult.output, maxOutputChars),
          })),
        );
      }

      if (text) {
        console.log(`${prefix} text:`, text);
      }
    },
    onFinish({ steps }: FinishLog) {
      console.log(`${prefix} steps:`, steps.length);
    },
  };
}

import { Meilisearch } from "meilisearch";
import { describe, expect, test, vi } from "vite-plus/test";

import { CLIENT_AGENT, resolveClient } from "../resolve-client.ts";

describe("resolveClient", () => {
  test("returns the provided client", () => {
    const client = { index: vi.fn() } as unknown as Meilisearch;

    expect(resolveClient({ client, description: "Search" })).toBe(client);
  });

  test("creates a Meilisearch client from host and apiKey", () => {
    const client = resolveClient({
      host: "http://localhost:7700",
      apiKey: "test-key",
      description: "Search",
    });

    expect(client).toBeInstanceOf(Meilisearch);
    expect(client.config.host).toBe("http://localhost:7700");
    expect(client.config.apiKey).toBe("test-key");
    expect(client.config.clientAgents).toEqual([CLIENT_AGENT]);
  });

  test("creates a Meilisearch client from host without apiKey", () => {
    const client = resolveClient({
      host: "http://localhost:7700",
      description: "Search",
    });

    expect(client).toBeInstanceOf(Meilisearch);
    expect(client.config.host).toBe("http://localhost:7700");
  });

  test("sends the integration agent in the X-Meilisearch-Client header", async () => {
    const fetchMock = vi.fn().mockResolvedValue(
      new Response(JSON.stringify({ hits: [] }), {
        status: 200,
        headers: { "Content-Type": "application/json" },
      }),
    );
    vi.stubGlobal("fetch", fetchMock);

    try {
      const client = resolveClient({
        host: "http://localhost:7700",
        apiKey: "test-key",
        description: "Search",
      });

      await client.index("movies").search("shoes");

      const init = fetchMock.mock.calls[0]?.[1] as RequestInit;
      const header = new Headers(init.headers).get("X-Meilisearch-Client");

      expect(header).toContain(CLIENT_AGENT);
    } finally {
      vi.unstubAllGlobals();
    }
  });

  test("throws when neither client nor host is provided", () => {
    expect(() => resolveClient({ description: "Search" } as never)).toThrow(/client|host/i);
  });

  test("prefers client when both client and host are provided", () => {
    const client = { index: vi.fn() } as unknown as Meilisearch;

    expect(
      resolveClient({
        client,
        host: "http://localhost:7700",
        apiKey: "test-key",
        description: "Search",
      }),
    ).toBe(client);
  });
});

import type { ToolSet, TypedToolCall, TypedToolResult } from "ai";
import { expect } from "vite-plus/test";

type ToolCallsResult<TOOLS extends ToolSet = ToolSet> = {
  toolCalls: Array<TypedToolCall<TOOLS>>;
};

type ToolResultsResult<TOOLS extends ToolSet = ToolSet> = {
  toolResults: Array<TypedToolResult<TOOLS>>;
};

export type ExpectToolCalledOptions = {
  times?: number | { min?: number };
};

function matchesName(toolName: string, name?: string): boolean {
  return name === undefined || toolName === name;
}

export function getToolCalls<TOOLS extends ToolSet>(
  result: ToolCallsResult<TOOLS>,
  name?: string,
): TypedToolCall<TOOLS>[] {
  return result.toolCalls.filter((call) => matchesName(call.toolName, name));
}

export function getToolResults<TOOLS extends ToolSet>(
  result: ToolResultsResult<TOOLS>,
  name?: string,
): TypedToolResult<TOOLS>[] {
  return result.toolResults.filter((toolResult) => matchesName(toolResult.toolName, name));
}

export function expectToolCalled<TOOLS extends ToolSet>(
  result: ToolCallsResult<TOOLS>,
  name: string,
  options: ExpectToolCalledOptions = {},
): TypedToolCall<TOOLS>[] {
  const calls = getToolCalls(result, name);
  const { times = { min: 1 } } = options;

  if (typeof times === "number") {
    expect(calls, `expected tool "${name}" to be called ${times} time(s)`).toHaveLength(times);
  } else {
    const min = times.min ?? 1;
    expect(
      calls.length,
      `expected tool "${name}" to be called at least ${min} time(s)`,
    ).toBeGreaterThanOrEqual(min);
  }

  return calls;
}

export function expectToolCallInput<TOOLS extends ToolSet>(
  result: ToolCallsResult<TOOLS>,
  name: string,
  partialInput: unknown,
): TypedToolCall<TOOLS> {
  const [call] = expectToolCalled(result, name);
  expect(call.input).toEqual(expect.objectContaining(partialInput as Record<string, unknown>));
  return call;
}

export function expectToolResult<TOOLS extends ToolSet>(
  result: ToolResultsResult<TOOLS>,
  name: string,
  matcher?: Record<string, unknown> | ((output: unknown) => void),
): TypedToolResult<TOOLS> {
  const results = getToolResults(result, name);
  expect(results, `expected tool "${name}" to have at least one result`).not.toHaveLength(0);

  const toolResult = results[0]!;

  if (typeof matcher === "function") {
    matcher(toolResult.output);
  } else if (matcher !== undefined) {
    expect(toolResult.output).toEqual(expect.objectContaining(matcher));
  }

  return toolResult;
}

